    char sep = File.separatorChar;
    path = path.replace('/', sep).replace('\\', sep);

    // make sure we are dealing with an absolute path
    if (!isAbsolutePath(path)) {
        throw new BuildException(path + " is not an absolute path");
    }
    String root = null;
    if (isWindowsPath(path)) {
        root = extractWindowsRoot(path, sep);
    } else if (isUNCPath(path)) {
        root = extractUNCRoot(path, sep);
    } else {
        root = File.separator;
        path = path.substring(1);
    }
    return new String[] {root, path};
}

private boolean isWindowsPath(String path) {
    int colon = path.indexOf(':');
    return colon > 0 && (ON_DOS || ON_NETWARE);
}

private String extractWindowsRoot(String path, char sep) {
    int colon = path.indexOf(':');
    int next = colon + 1;
    String root = path.substring(0, next);
    root += sep;
    //remove the initial separator; the root has it.
    next = (path.length() > next && path.charAt(next) == sep) ? next + 1 : next;

    StringBuffer sbPath = new StringBuffer();
    // Eliminate consecutive slashes after the drive spec:
    char[] ca = path.toCharArray();
    for (int i = next; i < ca.length; i++) {
        if (ca[i] != sep || ca[i - 1] != sep) {
            sbPath.append(ca[i]);
        }
    }
    path = sbPath.toString();
    return root;
}

private boolean isUNCPath(String path) {
    return path.length() > 1 && path.charAt(1) == sep;
}

private String extractUNCRoot(String path, char sep) {
    int nextsep = path.indexOf(sep, 2);
    nextsep = path.indexOf(sep, nextsep + 1);
    String root = (nextsep > 2) ? path.substring(0, nextsep + 1) : path;
    path = path.substring(root.length());
    return root;
}

