private void processArgs(String[] args) {
    ArgumentsContext context = new ArgumentsContext();
    setupInitialContext(context);

    for (int i = 0; i < args.length; i++) {
        i = processArgument(args, i, context);
    }

    handleArgumentProcessingResults(context);
    finalizeBuildFile(context);
    normalizeAndLoadProperties(context);
    redirectOutputIfRequired(context);
    readyToRun = true;
}

private void setupInitialContext(ArgumentsContext context) {
    contextArgsDefaults(context);
}

private void contextArgsDefaults(ArgumentsContext context) {
    context.logger = null;
    context.searchForFile = false;
    context.searchForThis = null;
}

private int processArgument(String[] args, int i, ArgumentsContext context) {
    String arg = args[i];

    if (isHelpRequest(arg)) {
        context.justPrintUsage = true;
    } else if (isVersionRequest(arg)) {
        context.justPrintVersion = true;
    } else if (isDiagnosticsRequest(arg)) {
        context.justPrintDiagnostics = true;
    } else if (isQuietModeRequest(arg)) {
        msgOutputLevel = Project.MSG_WARN;
    } else if (isVerboseModeRequest(arg)) {
        msgOutputLevel = Project.MSG_VERBOSE;
    } else if (isDebugModeRequest(arg)) {
        msgOutputLevel = Project.MSG_DEBUG;
    } else if (isSilentModeRequest(arg)) {
        context.silent = true;
    } else if (isNoInputModeRequest(arg)) {
        context.allowInput = false;
    } else if (isLogFileRequest(arg)) {
        i = handleLogFile(args, i, context);
    } else if (isBuildFileRequest(arg)) {
        i = handleArgBuildFile(args, i);
    } else if (isListenerRequest(arg)) {
        i = handleArgListener(args, i);
    } else if (isDefinePropertyRequest(arg)) {
        i = handleArgDefine(args, i);
    } else if (isLoggerRequest(arg)) {
        i = handleArgLogger(args, i);
    } else if (isInputHandlerRequest(arg)) {
        i = handleArgInputHandler(args, i);
    } else if (isEmacsModeRequest(arg)) {
        context.emacsMode = true;
    } else if (isProjectHelpRequest(arg)) {
        context.projectHelp = true;
    } else if (isFindRequest(arg)) {
        i = handleFindRequest(args, i, context);
    } else if (isPropertyFileRequest(arg)) {
        i = handleArgPropertyFile(args, i);
    } else if (isKeepGoingRequest(arg)) {
        context.keepGoingMode = true;
    } else if (isNiceRequest(arg)) {
        i = handleArgNice(args, i);
    } else if (isLaunchCommand(arg)) {
        handleLaunchCommand(arg);
    } else if (isAutoProxyRequest(arg)) {
        context.proxy = true;
    } else if (arg.startsWith("-")) {
        i = handleUnknownArgument(args, i, context);
    } else {
        targets.addElement(arg);
    }

    return i;
}

