private int handleLogFile(String[] args, int i, ArgumentsContext context) {
    try {
        File logFile = new File(args[i + 1]);
        i++;
        PrintStream logTo = new PrintStream(new FileOutputStream(logFile));
        context.logTo = logTo;
        isLogFileUsed = true;
    } catch (IOException ioe) {
        String msg = "Cannot write on the specified log file. "
            + "Make sure the path exists and you have write "
            + "permissions.";
        throw new BuildException(msg);
    } catch (ArrayIndexOutOfBoundsException aioobe) {
        String msg = "You must specify a log file when "
            + "using the -log argument";
        throw new BuildException(msg);
    }
    return i;
}

private int handleFindRequest(String[] args, int i, ArgumentsContext context) {
    context.searchForFile = true;
    if (i < args.length - 1) {
        context.searchForThis = args[++i];
    }
    return i;
}

private int handleUnknownArgument(String[] args, int i, ArgumentsContext context) {
    ArgumentProcessorRegistry processorRegistry = ArgumentProcessorRegistry.getInstance();
    boolean processed = false;

    for (ArgumentProcessor processor : processorRegistry.getProcessors()) {
        int newI = processor.readArguments(args, i);
        if (newI != -1) {
            List<String> extraArgs = context.extraArguments.get(processor.getClass());
            if (extraArgs == null) {
                extraArgs = new ArrayList<>();
                context.extraArguments.put(processor.getClass(), extraArgs);
            }
            for (; i < newI && i < args.length; i++) {
                extraArgs.add(args[i]);
            }
            processed = true;
            break;
        }
    }

    if (!processed) {
        String msg = "Unknown argument: " + args[i];
        System.err.println(msg);
        printUsage();
        throw new BuildException("");
    }

    return i;
}

private void handleArgumentProcessingResults(ArgumentsContext context) {
    handleVersionLogging(context);
    handleEarlyExit(context);
}

private void handleVersionLogging(ArgumentsContext context) {
    if (msgOutputLevel >= Project.MSG_VERBOSE || context.justPrintVersion) {
        printVersion(msgOutputLevel);
    }
}

private void handleEarlyExit(ArgumentsContext context) {
    if (context.justPrintUsage || context.justPrintVersion || context.justPrintDiagnostics) {
        if (context.justPrintUsage) {
            printUsage();
        }
        if (context.justPrintDiagnostics) {
            Diagnostics.doReport(System.out, msgOutputLevel);
        }
        return;
    }
}

private void finalizeBuildFile(ArgumentsContext context) {
    if (buildFile == null) {
        if (context.searchForFile) {
            handleSearchForBuildFile(context);
        } else {
            handleDefaultBuildFileSearch();
        }
    }

    validateBuildFile();
}

private void handleSearchForBuildFile(ArgumentsContext context) {
    if (context.searchForThis != null) {
        buildFile = findBuildFile(System.getProperty("user.dir"), context.searchForThis);
        if (buildFile == null) {
            throw new BuildException("Could not locate a build file!");
        }
    } else {
        handleDefaultSearchWithoutSearchFile();
    }
}

private void handleDefaultSearchWithoutSearchFile() {
    Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
    do {
        ProjectHelper helper = it.next();
        String searchForThis = helper.getDefaultBuildFile();
        buildFile = findBuildFile(System.getProperty("user.dir"), searchForThis);
    } while (buildFile == null && it.hasNext());
    if (buildFile == null) {
        throw new BuildException("Could not locate a build file!");
    }
}

private void handleDefaultBuildFileSearch() {
    Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
    do {
        ProjectHelper helper = it.next();
        buildFile = new File(helper.getDefaultBuildFile());
        if (msgOutputLevel >= Project.MSG_VERBOSE) {
            System.out.println("Trying the default build file: " + buildFile);
        }
    } while (!buildFile.exists() && it.hasNext());
}

private void validateBuildFile() {
    if (!buildFile.exists()) {
        System.out.println("Buildfile: " + buildFile + " does not exist!");
        throw new BuildException("Build failed");
    }

    if (buildFile.isDirectory()) {
        File whatYouMeant = new File(buildFile, "build.xml");
        if (whatYouMeant.isFile()) {
            buildFile = whatYouMeant;
        } else {
            System.out.println("What? Buildfile: " + buildFile + " is a dir!");
            throw new BuildException("Build failed");
        }
    }

    buildFile = FileUtils.getFileUtils().normalize(buildFile.getAbsolutePath());
}

private void normalizeAndLoadProperties(ArgumentsContext context) {
    loadPropertyFiles();
    if (msgOutputLevel >= Project.MSG_INFO) {
        System.out.println("Buildfile: " + buildFile);
    }
}

private void redirectOutputIfRequired(ArgumentsContext context) {
    if (context.logTo != null) {
        out = context.logTo;
        err = context.logTo;
        System.setOut(out);
        System.setErr(err);
    }
}

