public Object findOperationByName(Object trans, String opname) {
    if (!(trans instanceof Transition)) {
        throw new IllegalArgumentException();
    }

    try {
        Object sm = getStateMachine(trans);
        if (sm == null) {
            return null;
        }

        Object context = Model.getFacade().getContext(sm);
        if (context == null) {
            return null;
        }

        Classifier classifier = getOwnerClassifier(context);
        if (classifier != null) {
            Object found = findOperationInClassifier(classifier, opname);
            if (found != null) {
                return found;
            }
        }

        Namespace pack = resolvePackageForOperationSearch(context, classifier);
        if (pack != null) {
            return findOperationInOwnedClassifiers(pack, opname);
        }

        return null;
    } catch (InvalidObjectException e) {
        throw new InvalidElementException(e);
    }
}

