def _extract_scheme(elem, prefixes):
    scheme = elem.get('scheme') or None
    if scheme is None:
        return None, None

    prefix, sep, rest = scheme.partition(':')
    if not sep or not prefix or not rest:
        return None, None

    ns = prefixes.get(prefix)
    if ns is None:
        return None, None

    return ns, rest

