        ActionList popUpActions =
            new ActionList(super.getPopUpActions(me), isReadOnly());

        addContextPopupActions(popUpActions);
        addRemoveFromDiagramAction(popUpActions);
        addDeleteModelElementsAction(popUpActions);
        addCritiquesSubmenu(popUpActions, me);
        addStereotypesSubmenu(popUpActions);

        return popUpActions;
    }

    private void addContextPopupActions(ActionList popUpActions) {
        final List<Action> modulesActions =
            ContextActionFactoryManager.getContextPopupActions();

        for (Action a : modulesActions) {
            if (a instanceof List) {
                JMenu m = new JMenu((Action) a);
                popUpActions.add(m);
                for (Action subAction : (List<Action>) a) {
                    m.add(subAction);
                }
            } else {
                popUpActions.add(a);
            }
        }
    }

    private void addRemoveFromDiagramAction(ActionList popUpActions) {
        if (removeFromDiagram) {
            popUpActions.add(
                    ProjectActions.getInstance().getRemoveFromDiagramAction());
            popupAddOffset++;
        }
        popupAddOffset++;
    }

    private void addDeleteModelElementsAction(ActionList popUpActions) {
        popUpActions.add(new ActionDeleteModelElements());
    }

    private void addCritiquesSubmenu(ActionList popUpActions, MouseEvent me) {
        if (TargetManager.getInstance().getTargets().size() != 1) {
            return;
        }
        ToDoList list = Designer.theDesigner().getToDoList();
        List<ToDoItem> items = list.elementListForOffender(getOwner());
        if (items == null || items.isEmpty()) {
            return;
        }

        ArgoJMenu critiques = new ArgoJMenu("menu.popup.critiques");
        ToDoItem itemUnderMouse = hitClarifier(me.getX(), me.getY());
        if (itemUnderMouse != null) {
            critiques.add(new ActionGoToCritique(itemUnderMouse));
            critiques.addSeparator();
        }
        for (ToDoItem item : items) {
            if (item != itemUnderMouse) {
                critiques.add(new ActionGoToCritique(item));
            }
        }
        popUpActions.add(0, new JSeparator());
        popUpActions.add(0, critiques);
    }

    private void addStereotypesSubmenu(ActionList popUpActions) {
        Action[] stereoActions = getApplyStereotypeActions();
        if (stereoActions == null || stereoActions.length == 0) {
            return;
        }
        popUpActions.add(0, new JSeparator());
        ArgoJMenu stereotypes = new ArgoJMenu(
                "menu.popup.apply-stereotypes");
        for (int i = 0; i < stereoActions.length; ++i) {
            stereotypes.addCheckItem(stereoActions[i]);
        }
        popUpActions.add(0, stereotypes);
    }

    /**
     * Get the set of Actions which valid for adding/removing
     * Stereotypes on the ModelElement of this Fig's owner.
     *
     * @return array of Actions
     */
    protected Action[] getApplyStereotypeActions() {
        Collection<Object> elements = new ArrayList<Object>();
        Object owner = getOwner();
        if (owner != null) {
            elements.add(owner);
        }
        for (Object o : TargetManager.getInstance().getTargets()) {
            Object element = extractModelElement(o);
            if (element != null && element != owner) {
                elements.add(element);
            }
        }
        return StereotypeUtility.getApplyStereotypeActions(elements);
    }

    private Object extractModelElement(Object o) {
        if (Model.getFacade().isAUMLElement(o)) {
            return o;
        } else if (o instanceof Fig) {
            return ((Fig) o).getOwner();
        }
        return null;
    }

    /**
     * distance formula: (x-h)^2 + (y-k)^2 = distance^2
     *
     * @param p1 point
     * @param p2 point
     * @return the square of the distance
     */
    protected int getSquaredDistance(Point p1, Point p2) {
        int xSquared = p2.x - p1.x;
        xSquared *= xSquared;
        int ySquared = p2.y - p1.y;
        ySquared *= ySquared;
        return xSquared + ySquared;
    }

    /**
     * @param g the <code>Graphics</code> object
     */
    public void paintClarifiers(Graphics g) {
        int iconPos = 25, gap = 1, xOff = -4, yOff = -4;
        Point p = new Point();
        ToDoList tdList = Designer.theDesigner().getToDoList();
        paintClarifiersForOffender(tdList, getOwner(), g, iconPos, gap, xOff, yOff, p);
        paintClarifiersForOffender(tdList, this, g, iconPos, gap, xOff, yOff, p);
    }

    private void paintClarifiersForOffender(ToDoList tdList, Object offender,
            Graphics g, int iconPos, int gap, int xOff, int yOff, Point p) {
        List<ToDoItem> items = tdList.elementListForOffender(offender);
        for (ToDoItem item : items) {
            Icon icon = item.getClarifier();
            setupClarifier(icon, item);
            if (icon != null) {
                stuffPointAlongPerimeter(iconPos, p);
                icon.paintIcon(null, g, p.x + xOff, p.y + yOff);
                iconPos += icon.getIconWidth() + gap;
            }
        }
    }

    private void setupClarifier(Icon icon,ToDoItem item) {
        if (icon instanceof Clarifier) {
            ((Clarifier) icon).setFig(this);
            ((Clarifier) icon).setToDoItem(item);
        }
    }

    /**
     * The user clicked on the clarifier.
     *
     * @param x the x of the point clicked
     * @param y the y of the point clicked
     * @return the todo item clicked
     */
    public ToDoItem hitClarifier(int x, int y) {
        Point p = new Point();
        ToDoList tdList = Designer.theDesigner().getToDoList();

        ToDoItem item =
            hitClarifierForOffender(tdList, getOwner(), x, y, p);
        if (item != null) {
            return item;
        }
        item = hitClarifierForOffender(tdList, this, x, y, p);
        if (item != null) {
            return item;
        }
        return null;
    }

    private ToDoItem hitClarifierForOffender(ToDoList tdList, Object offender,
            int x, int y, Point p) {
        List<ToDoItem> items = tdList.elementListForOffender(offender);
        for (ToDoItem item : items) {
            Icon icon = item.getClarifier();
            stuffPointAlongPerimeter(25, p);
            if (isHitByClarifier(icon, p, x, y)) {
                return item;
            }
        }
        for (ToDoItem item : items) {
            Icon icon = item.getClarifier();
            if (icon instanceof Clarifier) {
                ((Clarifier) icon).setFig(this);
                ((Clarifier) icon).setToDoItem(item);
                if (((Clarifier) icon).hit(x, y)) {
                    return item;
                }
            }
        }
        return null;
    }

    private boolean isHitByClarifier(Icon icon, Point p, int x, int y) {
        if (icon == null) {
            return false;
        }
        int xOff = -4, yOff = -4;
        int width = icon.getIconWidth();
        int height = icon.getIconHeight();
        return y >= p.y + yOff
            && y <= p.y + height + yOff
            && x >= p.x + xOff
            && x <= p.x + width + xOff;
    }

