  }

  /**
   * Compares two LocatedBlocks sequences for equality by block identity.
   * @param oldInfo previous LocatedBlocks
   * @param newInfo new LocatedBlocks
   * @return true if sequences match block-for-block
   */
  private boolean blockListsMatch(LocatedBlocks oldInfo, LocatedBlocks newInfo) {
    Iterator<LocatedBlock> oldIter = oldInfo.getLocatedBlocks().iterator();
    Iterator<LocatedBlock> newIter = newInfo.getLocatedBlocks().iterator();
    while (oldIter.hasNext() && newIter.hasNext()) {
      if (!oldIter.next().getBlock().equals(newIter.next().getBlock())) {
        return false;
      }
    }
    return true;
  }

  /**
   * Determines the length of the last block, handling incomplete blocks.
   * @param newInfo the newly fetched LocatedBlocks
   * @return block length, 0 if empty, -1 if unavailable, or actual length
   */
  private long computeLastBlockLength(LocatedBlocks newInfo) throws IOException {
    if (newInfo.isLastBlockComplete()) {
      return 0;
    }
    final LocatedBlock last = newInfo.getLastLocatedBlock();
    if (last == null) {
      return 0;
    }
    if (last.getLocations().length == 0) {
      return last.getBlockSize() == 0 ? 0 : -1;
    }
    final long len = readBlockLength(last);
    last.getBlock().setNumBytes(len);
    return len;
  }

