/**
 * Try to find a datanode based on network topology, first machine-local
 * then rack-local, then any node.
 */
private DatanodeDescriptor selectBestDatanodeDescriptorFromRackOrCluster(DatanodeID dnId) {
  String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);

  List<Node> rackNodes = getNetworkTopology()
      .getDatanodesInRack(networkLocation);
  if (rackNodes != null) {
    DatanodeDescriptor candidate = findMachineLocalNode(rackNodes, dnId.getIpAddr());
    if (candidate != null) {
      return candidate;
    }

    if (!rackNodes.isEmpty()) {
      return (DatanodeDescriptor) rackNodes.get(DFSUtil.getRandom().nextInt(rackNodes.size()));
    }
  }

  return (DatanodeDescriptor) getNetworkTopology()
      .chooseRandom(NodeBase.ROOT);
}

/**
 * Find the first node in the provided list matching the given IP address.
