private DatanodeDescriptor findMachineLocalNode(List<Node> nodes, String targetIp) {
  for (Node node : nodes) {
    DatanodeDescriptor descriptor = (DatanodeDescriptor) node;
    if (descriptor.getIpAddr().equals(targetIp)) {
      return descriptor;
    }
  }
  return null;
}

