    StorageGroup proxy = findProxyOnSameRack(targetDN);
    if (proxy != null && addTo(proxy)) {
      return true;
    }

    // find out a non-busy replica
    for (StorageGroup loc : block.getLocations()) {
      if (addTo(loc)) {
        return true;
      }
    }

    return false;
  }

  /**
