  // Extracted: handle apply-time errors (isolates recovery complexity)
  private long handleApplyError(FSEditLogOp op, MetaRecoveryContext recovery,
      Throwable e, long expectedTxId) {
    LOG.error("Encountered exception on operation " + op, e);
    if (recovery == null) {
      throw e instanceof IOException? (IOException)e: new IOException(e);
    }

    MetaRecoveryContext.editLogLoaderPrompt("Failed to " +
     "apply edit log operation " + op + ": error " +
     e.getMessage(), recovery, "applying edits");
    return expectedTxId;
  }

  // Extracted: conditional logging of progress
  private void logProgressIfIntervalReached(FSEditLogOp op, long lastAppliedTxId,
      long expectedStartingTxId, long numTxns, long lastLogTime) {
    if (op.hasTransactionId()) {
      long now = monotonicNow();
      if (now - lastLogTime > REPLAY_TRANSACTION_LOG_INTERVAL) {
        long deltaTxId = lastAppliedTxId - expectedStartingTxId + 1;
        int percent = Math.round((float) deltaTxId / numTxns * 100);
        LOG.info("replaying edit log: " + deltaTxId + "/" + numTxns
            + " transactions completed. (" + percent + "%)");
      }
    }
  }

