/**
 * Internal implementation of listFiles to reduce Cognitive Complexity.
 * Wraps the iterator logic in a helper method.
 */
private RemoteIterator<LocatedFileStatus> listFilesInternal(
    final Path f, final boolean recursive) throws AccessControlException,
    FileNotFoundException, UnsupportedFileSystemException, 
    IOException {
  return new RemoteIterator<LocatedFileStatus>() {
    private final Stack<RemoteIterator<LocatedFileStatus>> itors =
        new Stack<RemoteIterator<LocatedFileStatus>>();
    private RemoteIterator<LocatedFileStatus> curItor =
        listLocatedStatus(f);
    private LocatedFileStatus curFile;

    @Override
    public boolean hasNext() throws IOException {
      while (curFile == null) {
        if (curItor.hasNext()) {
          handleFileStat(curItor.next());
        } else if (!itors.empty()) {
          curItor = itors.pop();
        } else {
          return false;
        }
      }
      return true;
    }

    @Override
    public LocatedFileStatus next() throws IOException {
      if (hasNext()) {
        LocatedFileStatus result = curFile;
        curFile = null;
        return result;
      }
      throw new java.util.NoSuchElementException("No more entry in " + f);
    }

    /**
     * Process the input stat:
     * - files are returned directly.
     * - symlinks are resolved and then handled.
     * - directories are traversed if recursive is true.
     */
    private void handleFileStat(LocatedFileStatus stat) throws IOException {
      if (stat.isFile()) {
        curFile = stat;
      } else if (stat.isSymlink()) {
        resolveAndHandleSymlink(stat);
      } else if (recursive) {
        // Directory and recursive=true
        itors.push(curItor);
        curItor = listLocatedStatus(stat.getPath());
      }
    }

    /**
     * Resolve a symlink and decide whether to descend or return.
     */
    private void resolveAndHandleSymlink(LocatedFileStatus stat)
        throws IOException {
      FileStatus symstat = FileContext.this.getFileStatus(stat.getSymlink());
      if (symstat.isFile()) {
        curFile = stat; // Return symlink status when target is file
      } else if (symstat.isDirectory() && recursive) {
        itors.push(curItor);
        curItor = listLocatedStatus(stat.getPath());
      }
      // Otherwise ignore non-recursive or non-file symlink targets
    }
  };
}

 * @throws UnexpectedServerException If server implementation throws 
