private boolean isLastBlockComplete() {
    return locatedBlocks.isLastBlockComplete();
  }

  private boolean isLastBlockComplete(LocatedBlocks blocks) {
    return blocks.isLastBlockComplete();
  }

  private boolean isLastBlockComplete(LocatedBlock last) {
    return last != null && last.getLocations().length > 0;
  }

  private boolean hasZeroLengthBlock(LocatedBlock last) {
    return last != null && last.getBlockSize() == 0;
  }

  private boolean hasNoLocations(LocatedBlock last) {
    return last != null && last.getLocations().length == 0;
  }

  private boolean shouldFetchNewBlockInfo(LocatedBlocks newInfo) {
    return newInfo != null && locatedBlocks != null;
  }

  private boolean blockListsDiffer(Iterator<LocatedBlock> oldIter, Iterator<LocatedBlock> newIter) {
    while (oldIter.hasNext() && newIter.hasNext()) {
      if (!oldIter.next().getBlock().equals(newIter.next().getBlock())) {
        return true;
      }
    }
    return false;
  }

  private boolean shouldReturnZero() {
    return hasZeroLengthBlock(locatedBlocks.getLastLocatedBlock());
  }

  private boolean shouldReturnNegativeOne() {
    return hasNoLocations(locatedBlocks.getLastLocatedBlock());
  }

  private boolean isLastBlockComplete(LocatedBlocks newInfo) {
    return newInfo != null && newInfo.isLastBlockComplete();
  }

  private boolean shouldProcessLastBlock(LocatedBlocks newInfo) {
    return newInfo != null && !newInfo.isLastBlockComplete();
  }

  private boolean isValidLocatedBlock(LocatedBlock last) {
    return last != null && last.getLocations().length > 0;
  }

  private boolean shouldFetchBlockLength(LocatedBlock last) {
    return last != null && last.getLocations().length > 0 && last.getBlockSize() > 0;
  }

  private boolean isReplicaNotFound(IOException ioe) {
    return ioe instanceof RemoteException &&
        (((RemoteException) ioe).unwrapRemoteException() instanceof ReplicaNotFoundException);
  }

  private boolean shouldRetryForLastBlockLength(int retries) {
    return retries > 0 && lastBlockBeingWrittenLength == -1;
  }

  private boolean isReadOffsetWithinCompleteBlock(long offset, long lengthOfCompleteBlk) {
    return offset < lengthOfCompleteBlk;
  }

  private boolean isReadLengthPastCompleteBlock(long offset, long length, long lengthOfCompleteBlk) {
    return offset + length > lengthOfCompleteBlk;
  }

  private boolean isBlockCached(int blockIdx, LocatedBlocks locatedBlocks) {
    return blockIdx >= 0 && blockIdx < locatedBlocks.locatedBlockCount();
  }

  private boolean isBlockAvailable(LocatedBlock blk, long curOff) {
    return blk != null && curOff >= blk.getStartOffset();
  }

  private boolean shouldFetchNewBlocks(LocatedBlock blk, long curOff) {
    return blk == null || curOff < blk.getStartOffset();
  }

  private boolean isOffsetValid(long offset, long fileLength) {
    return offset >= 0 && offset < fileLength;
  }

  private boolean isOffsetAtOrPastFileLength(long offset, long fileLength) {
    return offset >= fileLength;
  }

